{"command":"python3 - << 'PY'
import subprocess, os, shutil, stat
EXE="/workspace/executable"
def run(setup, flags, inp=b"/tmp/ideas2\n", desc=""):
    home="/tmp/thPy"
    shutil.rmtree(home, ignore_errors=True)
    os.makedirs(home+"/.config/eureka", exist_ok=True)
    setup(home)
    env=dict(os.environ); env.update({"HOME":home,"RUST_LOG":"debug","EDITOR":"/tmp/editor.sh","PAGER":"/tmp/pager.sh"})
    for f in ["/tmp/editor.log","/tmp/pager.log"]:
        try: os.remove(f)
        except: pass
    try:
        p=subprocess.run([EXE]+flags, input=inp, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=2)
        out,err,ec=p.stdout[:400],p.stderr.decode(errors='replace').strip().replace("\n"," | "),p.returncode
    except subprocess.TimeoutExpired as e:
        out,err,ec=(e.stdout or b'')[:400],(e.stderr or b'').decode(errors='replace'),"TIMEOUT"
    print(f"== {desc} flags={flags} exit={ec}")
    print(" out:",out); print(" err:",err)
    # list
    for root,dirs,files in os.walk(home):
        for fn in files:
            fp=os.path.join(root,fn)
            try: data=open(fp,'rb').read()
            except Exception as ex: data=str(ex).encode()
            print(" file:",fp,data[:100])
        for d in dirs:
            print(" dir:", os.path.join(root,d))
    print()

def mk_dir_cfg(home): os.makedirs(home+"/.config/eureka/config.json")
def mk_unreadable(home):
    open(home+"/.config/eureka/config.json","w").write('{"repo":"/tmp/ideas2"}')
    os.chmod(home+"/.config/eureka/config.json",0o000)
def mk_symlink_missing(home): os.symlink("/no/such", home+"/.config/eureka/config.json")
def mk_symlink_valid(home):
    open("/tmp/realcfg.json","w").write('{"repo":"/tmp/ideas2"}')
    os.symlink("/tmp/realcfg.json", home+"/.config/eureka/config.json")
def mk_fifo(home): os.mkfifo(home+"/.config/eureka/config.json")
def mk_nothing(home): pass

run(mk_dir_cfg, ["--view"], inp=b"", desc="config is directory view")
run(mk_dir_cfg, [], desc="config is directory normal")
run(mk_dir_cfg, ["--clear-config"], inp=b"",desc="config is directory clear")
run(mk_unreadable, ["--view"], inp=b"", desc="unreadable view (agent maybe root? whoami)")
run(mk_symlink_missing, ["--view"], inp=b"", desc="symlink missing view")
run(mk_symlink_missing, [], desc="symlink missing normal")
run(mk_symlink_valid, ["--view"], inp=b"", desc="symlink valid view")
run(mk_symlink_valid, ["--clear-config"], inp=b"", desc="symlink valid clear")
PY
whoami; id
"}

