import subprocess, os, shutil
EXE="/workspace/executable"
def run(desc, envmods, flags=["--view"], inp=b""):
    # clean known dirs
    for d in ["/tmp/thXDG","/tmp/xdgcfg","/tmp/relxdg"]:
        shutil.rmtree(d, ignore_errors=True)
    os.makedirs("/tmp/thXDG", exist_ok=True)
    env=dict(os.environ); env.update({"HOME":"/tmp/thXDG","RUST_LOG":"debug","PAGER":"cat","EDITOR":"/tmp/editor.sh"})
    for k,v in envmods.items():
        if v is None: env.pop(k,None)
        else: env[k]=v
    try:
        p=subprocess.run([EXE]+flags, input=inp, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=2, cwd="/tmp")
        print(desc, "exit",p.returncode)
        print(" out",p.stdout[:500])
        print(" err",p.stderr.decode().strip().replace("\n"," | "))
    except subprocess.TimeoutExpired as e:
        print(desc,"TIMEOUT out", (e.stdout or b'')[:500], "err",(e.stderr or b''))
    for root,dirs,files in os.walk("/tmp/thXDG"):
        for fn in files: print("  file",os.path.join(root,fn), open(os.path.join(root,fn),'rb').read())
    for root,dirs,files in os.walk("/tmp/xdgcfg"):
        for fn in files: print("  xdgfile",os.path.join(root,fn), open(os.path.join(root,fn),'rb').read())
    print()
run("XDG_CONFIG_HOME abs setup", {"XDG_CONFIG_HOME":"/tmp/xdgcfg"}, flags=[], inp=b"/tmp/ideas2\n")
run("XDG_CONFIG_HOME abs view missing", {"XDG_CONFIG_HOME":"/tmp/xdgcfg"}, flags=["--view"])
