run("XDG_CONFIG_HOME empty setup", {"XDG_CONFIG_HOME":""}, flags=[], inp=b"/tmp/ideas2\n")
run("HOME unset view", {"HOME":None}, flags=["--view"])
run("HOME empty view", {"HOME":""}, flags=["--view"])
run("HOME unset XDG abs view", {"HOME":None, "XDG_CONFIG_HOME":"/tmp/xdgcfg"}, flags=["--view"])
run("HOME relative view", {"HOME":"relhome"}, flags=["--view"])
PY
