use git2::{Repository, PushOptions, RemoteCallbacks};
use std::env;
fn main() {
 let args:Vec<String>=env::args().collect(); let mode=&args[1]; let repo=Repository::open(&args[2]).unwrap();
 let mut remote = match repo.find_remote("origin") { Ok(r)=>r, Err(e)=>{println!("find_remote err: {}",e); return;}};
 println!("remote url={:?} pushurl={:?} name={:?}", remote.url(), remote.pushurl(), remote.name());
 let res = match mode.as_str() {
  "push_none" => remote.push(&["refs/heads/main:refs/heads/main"], None),
  "push_short" => remote.push(&["refs/heads/main"], None),
  "push_opts_default" => remote.push(&["refs/heads/main:refs/heads/main"], Some(&mut PushOptions::new())),
  "push_callbacks_empty" => { let mut opts=PushOptions::new(); opts.remote_callbacks(RemoteCallbacks::new()); remote.push(&["refs/heads/main:refs/heads/main"], Some(&mut opts)) },
  "anon_url_push" => {
     // remote.url() returns Result<&str> in git2 0.21
     let url = remote.url().unwrap_or("").to_owned();
     println!("anon url clone={:?}",url);
     match repo.remote_anonymous(&url) { Ok(mut anon)=> anon.push(&["refs/heads/main:refs/heads/main"], None), Err(e)=>Err(e)}
  },
  _=> panic!("mode")
 };
 match res { Ok(_)=>println!("push ok"), Err(e)=>println!("push err: {} class={:?} code={:?}",e,e.class(),e.code())}
}
EOF
