        fmt.Fprintf(logf, format+"\n", args...)
    }
    config := &ssh.ServerConfig{
        Config: ssh.Config{},
        NoClientAuth: false,
        PasswordCallback: func(conn ssh.ConnMetadata, password []byte) (*ssh.Permissions, error) {
            log("password auth user=%q pass=%q remote=%s version=%q", conn.User(), string(password), conn.RemoteAddr(), string(conn.ClientVersion()))
            if conn.User() == "testuser" && string(password) == "testpass" {
                return nil, nil
            }
            return nil, fmt.Errorf("password rejected")
        },
        PublicKeyCallback: func(conn ssh.ConnMetadata, key ssh.PublicKey) (*ssh.Permissions, error) {
            fp := ssh.FingerprintSHA256(key)
            log("publickey auth user=%q keytype=%s fp=%s remote=%s version=%q", conn.User(), key.Type(), fp, conn.RemoteAddr(), string(conn.ClientVersion()))
            return nil, nil
        },
        KeyboardInteractiveCallback: func(conn ssh.ConnMetadata, client ssh.KeyboardInteractiveChallenge) (*ssh.Permissions, error) {
            log("keyboard-interactive user=%q", conn.User())
            answers, err := client("", "", []string{"Password: "}, []bool{false})
            log(" keyboard answers=%q err=%v", answers, err)
            if err == nil && len(answers)==1 && conn.User()=="testuser" && answers[0]=="testpass" {
                return nil,nil
            }
            return nil, fmt.Errorf("keyboard rejected")
        },
        AuthLogCallback: func(conn ssh.ConnMetadata, method string, err error) {
            log("authlog user=%q method=%s err=%v", conn.User(), method, err)
        },
    }
    hostBytes, err := os.ReadFile("/tmp/sshserver/hostkey")
    if err != nil { panic(err) }
    signer, err := ssh.ParsePrivateKey(hostBytes)
    if err != nil { panic(err) }
    config.AddHostKey(signer)
    listener, err := net.Listen("tcp", "127.0.0.1:2222")
    if err != nil { panic(err) }
    log("listening")
    for {
        tcp, err := listener.Accept()
        if err != nil { continue }
        go func(tcp net.Conn) {
            sconn, chans, reqs, err := ssh.NewServerConn(tcp, config)
            if err != nil { log("handshake failed %v",err); return }
            log("connection established user=%q version=%q", sconn.User(), string(sconn.ClientVersion()))
            go ssh.DiscardRequests(reqs)
            for chReq := range chans {
                if chReq.ChannelType() != "session" { chReq.Reject(ssh.UnknownChannelType, "unknown"); continue }
                ch, reqs, err := chReq.Accept()
                if err != nil { continue }
                go handleSession(ch, reqs, log)
            }
        }(tcp)
    }
}

func handleSession(ch ssh.Channel, reqs <-chan *ssh.Request, log func(string,...interface{})) {
    defer ch.Close()
    for req := range reqs {
        log("session req type=%s wantReply=%v payload=%q", req.Type, req.WantReply, string(req.Payload))
        switch req.Type {
        case "env":
            req.Reply(true,nil)
        case "exec":
            // payload is string with 4-byte len prefix
            payload := req.Payload
            cmdline := ""
            if len(payload)>=4 {
                n := int(payload[0])<<24|int(payload[1])<<16|int(payload[2])<<8|int(payload[3])
                if 4+n <= len(payload) { cmdline=string(payload[4:4+n]) }
            }
            log("exec cmd=%q",cmdline)
            req.Reply(true,nil)
            // parse: git-receive-pack '<path>' or git-upload-pack '<path>'
            fields := strings.Fields(cmdline)
            if len(fields)<2 {
                log("bad cmd fields")
                ch.SendRequest("exit-status", false, []byte{0,0,0,1})
                return
            }
            prog := fields[0]
            path := strings.Trim(fields[1], "'\"")
            log("running %s %s",prog,path)
            cmd := exec.Command(prog, path)
            cmd.Stdin = ch
            cmd.Stdout = ch
            cmd.Stderr = ch.Stderr()
            err := cmd.Run()
            status := byte(0)
            if err != nil { log("cmd err %v",err); status=1 }
            ch.SendRequest("exit-status", false, []byte{0,0,0,status})
            return
        case "shell","pty-req":
            req.Reply(true,nil)
        default:
            if req.WantReply { req.Reply(false,nil) }
        }
    }
    io.Copy(io.Discard,ch)
}
