const TARGET: &str = "eureka";

type AppResult<T> = Result<T, Box<dyn Error>>;

// ---------------------------------------------------------------------------
// Logging
//
// A small logger matching the output conventions used by the reference
// program: messages are written to stderr as
//     " LEVEL target > message"
// with the level and target coloured when stderr is a terminal.  The
// RUST_LOG filter syntax (including directive lists and an optional
// "/regex" message filter) follows the usual env_logger conventions.
// ---------------------------------------------------------------------------

struct Directive {
    name: Option<String>,
    level: LevelFilter,
}

struct LogFilter {
    directives: Vec<Directive>,
    message_filter: Option<Regex>,
}

impl LogFilter {
    fn parse(spec: &str) -> LogFilter {
        let mut directives: Vec<Directive> = Vec::new();
        let mut message_filter: Option<Regex> = None;

        let mut parts = spec.split('/');
        let mods = parts.next();
        let filter = parts.next();
        if parts.next().is_some() {
            eprintln!(
                "warning: invalid logging spec '{}', ignoring it (too many '/'s)",
                spec
            );
            return LogFilter {
                directives: vec![Directive {
                    name: None,
                    level: LevelFilter::Error,
                }],
                message_filter: None,
            };
        }

        if let Some(mods) = mods {
            for part in mods.split(',') {
                if part.is_empty() {
                    continue;
                }
                let mut kv = part.split('=');
                let name_or_level = kv.next().unwrap_or("");
                match (kv.next(), kv.next()) {
                    (None, None) => {
                        if let Ok(level) = name_or_level.parse::<LevelFilter>() {
                            directives.push(Directive { name: None, level });
                        } else {
                            directives.push(Directive {
                                name: Some(name_or_level.to_owned()),
                                level: LevelFilter::Trace,
                            });
                        }
                    }
                    (Some(level_str), None) => {
                        let level_str = level_str.trim();
                        if level_str.is_empty() {
                            directives.push(Directive {
                                name: Some(name_or_level.to_owned()),
                                level: LevelFilter::Trace,
                            });
                        } else if let Ok(level) = level_str.parse::<LevelFilter>() {
                            directives.push(Directive {
                                name: Some(name_or_level.to_owned()),
                                level,
                            });
                        } else {
                            eprintln!(
                                "warning: invalid logging spec '{}', ignoring it",
                                level_str
                            );
                        }
                    }
                    _ => {
                        eprintln!(
                            "warning: invalid logging spec '{}', ignoring it",
                            part
                        );
                    }
                }
            }
        }

        if let Some(filter) = filter {
            match Regex::new(filter) {
                Ok(re) => message_filter = Some(re),
                Err(e) => {
                    eprintln!("warning: invalid regex filter - {}", e);
                }
            }
        }

        if directives.is_empty() {
            directives.push(Directive {
                name: None,
                level: LevelFilter::Error,
            });
        } else {
            directives.sort_by(|a, b| {
                a.name
                    .as_ref()
                    .map(|n| n.len())
                    .unwrap_or(0)
                    .cmp(&b.name.as_ref().map(|n| n.len()).unwrap_or(0))
            });
        }

        LogFilter {
            directives,
            message_filter,
        }
    }

    fn max_level(&self) -> LevelFilter {
        self.directives
            .iter()
            .map(|d| d.level)
            .max()
            .unwrap_or(LevelFilter::Off)
    }

    fn enabled(&self, metadata: &Metadata<'_>) -> bool {
        let level = metadata.level();
        let target = metadata.target();
        for directive in self.directives.iter().rev() {
            match &directive.name {
                Some(name) if !target.starts_with(name.as_str()) => {}
                _ => return level <= directive.level,
            }
        }
        false
    }

    fn matches(&self, record: &Record<'_>) -> bool {
        if !self.enabled(record.metadata()) {
            return false;
        }
        if let Some(re) = &self.message_filter {
            if !re.is_match(&record.args().to_string()) {
                return false;
            }
        }
        true
    }
}

struct Logger {
    filter: LogFilter,
    coloured: bool,
}

impl Log for Logger {
    fn enabled(&self, metadata: &Metadata<'_>) -> bool {
        self.filter.enabled(metadata)
    }

    fn log(&self, record: &Record<'_>) {
        if !self.filter.matches(record) {
            return;
        }
        let stderr = io::stderr();
        let mut out = stderr.lock();
        if self.coloured {
            let code = match record.level() {
                Level::Error => 31,
                Level::Warn => 33,
                Level::Info => 32,
                Level::Debug => 34,
                Level::Trace => 36,
            };
            let _ = writeln!(
                out,
                " \x1b[0m\x1b[{}m{}\x1b[0m \x1b[0m\x1b[1m{}\x1b[0m > {}",
                code,
                record.level(),
                record.target(),
                record.args()
            );
        } else {
            let _ = writeln!(
                out,
                " {} {} > {}",
                record.level(),
                record.target(),
                record.args()
            );
        }
    }

    fn flush(&self) {}
}

fn init_logger() {
    let filter = match env::var("RUST_LOG") {
        Ok(spec) => LogFilter::parse(&spec),
        Err(_) => LogFilter {
            directives: vec![Directive {
                name: None,
                level: LevelFilter::Error,
            }],
            message_filter: None,
        },
    };
    let max = filter.max_level();
    let coloured = io::stderr().is_terminal()
        && match env::var_os("TERM") {
            Some(v) => v != OsStr::new("dumb"),
            None => false,
        }
        && env::var_os("NO_COLOR").is_none();
    let logger = Logger { filter, coloured };
    if log::set_boxed_logger(Box::new(logger)).is_ok() {
        log::set_max_level(max);
    }
}

