#[derive(Debug)]
struct EurekaOptions {
    clear_config: bool,
    view: bool,
}

fn parse_options() -> EurekaOptions {
    let matches = Command::new("eureka")
        .version("2.0.0")
        .about("Input and store your ideas without leaving the terminal")
        .arg(
            Arg::new("clear-config")
                .long("clear-config")
                .action(ArgAction::SetTrue)
                .help("Clear your stored configuration"),
        )
        .arg(
            Arg::new("view")
                .short('v')
                .long("view")
                .action(ArgAction::SetTrue)
                .help("View ideas with your $PAGER env variable. If unset use less"),
        )
        .get_matches();

    EurekaOptions {
        clear_config: matches.get_flag("clear-config"),
        view: matches.get_flag("view"),
    }
}

fn config_dir() -> PathBuf {
    let base = match env::var("XDG_CONFIG_HOME") {
        Ok(val) => PathBuf::from(val),
        Err(_) => dirs::home_dir()
            .unwrap_or_default()
            .join(".config"),
    };
    base.join("eureka")
}

fn config_file() -> PathBuf {
    config_dir().join("config.json")
}

#[derive(Debug, Default, Serialize, Deserialize)]
struct Config {
    repo: PathBuf,
}

fn load_config() -> AppResult<Config> {
    let contents = fs::read_to_string(config_file())?;
    if contents.is_empty() {
        return Ok(Config::default());
    }
    Ok(serde_json::from_str(&contents)?)
}

fn save_config(repo_path: &str) -> AppResult<()> {
    let config = Config {
        repo: PathBuf::from(repo_path),
    };
    let contents = serde_json::to_string(&config)?;
    fs::write(config_file(), contents)?;
    Ok(())
}

fn clear_config() -> AppResult<()> {
    fs::remove_file(config_file())?;
    debug!(target: TARGET, "Cleared config");
    Ok(())
}

