fn get_user_input(prompt: &str) -> AppResult<String> {
    loop {
        print!("\x1b[0m\x1b[1m\x1b[32m{}\n\x1b[0m> ", prompt);
        let _ = io::stdout().flush();
        let mut input = String::new();
        io::stdin().read_line(&mut input)?;
        let trimmed = input.trim().to_owned();
        if !trimmed.is_empty() {
            return Ok(trimmed);
        }
    }
}

