struct Directive {
    name: Option<String>,
    level: LevelFilter,
}

struct LogFilter {
    directives: Vec<Directive>,
    message_filter: Option<Regex>,
}

impl LogFilter {
    fn parse(spec: &str) -> LogFilter {
        let mut directives: Vec<Directive> = Vec::new();
        let mut message_filter: Option<Regex> = None;

        let mut parts = spec.split('/');
        let mods = parts.next();
        let filter = parts.next();
        if parts.next().is_some() {
            eprintln!(
                "warning: invalid logging spec '{}', ignoring it (too many '/'s)",
                spec
            );
            return LogFilter {
                directives: vec![Directive {
                    name: None,
                    level: LevelFilter::Error,
                }],
                message_filter: None,
            };
        }

        if let Some(mods) = mods {
            for part in mods.split(',') {
                if part.is_empty() {
                    continue;
                }
                let mut kv = part.split('=');
                let name_or_level = kv.next().unwrap_or("");
                match (kv.next(), kv.next()) {
                    (None, None) => {
                        if let Ok(level) = name_or_level.parse::<LevelFilter>() {
                            directives.push(Directive { name: None, level });
                        } else {
                            directives.push(Directive {
                                name: Some(name_or_level.to_owned()),
                                level: LevelFilter::Trace,
                            });
                        }
                    }
                    (Some(level_str), None) => {
                        let level_str = level_str.trim();
                        if level_str.is_empty() {
                            directives.push(Directive {
                                name: Some(name_or_level.to_owned()),
                                level: LevelFilter::Trace,
                            });
                        } else if let Ok(level) = level_str.parse::<LevelFilter>() {
                            directives.push(Directive {
                                name: Some(name_or_level.to_owned()),
                                level,
                            });
                        } else {
                            eprintln!(
