                                level_str
                            );
                        }
                    }
                    _ => {
                        eprintln!(
                            "warning: invalid logging spec '{}', ignoring it",
                            part
                        );
                    }
                }
            }
        }

        if let Some(filter) = filter {
            match Regex::new(filter) {
                Ok(re) => message_filter = Some(re),
                Err(e) => {
                    eprintln!("warning: invalid regex filter - {}", e);
                }
            }
        }

        if directives.is_empty() {
            directives.push(Directive {
                name: None,
                level: LevelFilter::Error,
            });
        } else {
            directives.sort_by(|a, b| {
                a.name
                    .as_ref()
                    .map(|n| n.len())
                    .unwrap_or(0)
                    .cmp(&b.name.as_ref().map(|n| n.len()).unwrap_or(0))
            });
        }

        LogFilter {
            directives,
            message_filter,
        }
    }

