            }
        }
        false
    }

    fn matches(&self, record: &Record<'_>) -> bool {
        if !self.enabled(record.metadata()) {
            return false;
        }
        if let Some(re) = &self.message_filter {
            if !re.is_match(&record.args().to_string()) {
                return false;
            }
        }
