// ---------------------------------------------------------------------------
// Options and configuration file
// ---------------------------------------------------------------------------

#[derive(Debug)]
struct EurekaOptions {
    clear_config: bool,
    view: bool,
}

fn parse_options() -> EurekaOptions {
    let matches = Command::new("eureka")
        .version("2.0.0")
        .about("Input and store your ideas without leaving the terminal")
        .arg(
            Arg::new("clear-config")
                .long("clear-config")
                .action(ArgAction::SetTrue)
                .help("Clear your stored configuration"),
        )
        .arg(
            Arg::new("view")
                .short('v')
                .long("view")
                .action(ArgAction::SetTrue)
                .help("View ideas with your $PAGER env variable. If unset use less"),
        )
        .get_matches();

    EurekaOptions {
        clear_config: matches.get_flag("clear-config"),
        view: matches.get_flag("view"),
    }
}

fn config_dir() -> PathBuf {
    let base = match env::var("XDG_CONFIG_HOME") {
        Ok(val) => PathBuf::from(val),
        Err(_) => dirs::home_dir()
            .unwrap_or_default()
            .join(".config"),
    };
    base.join("eureka")
}

fn config_file() -> PathBuf {
    config_dir().join("config.json")
}

#[derive(Debug, Default, Serialize, Deserialize)]
struct Config {
    repo: PathBuf,
}

fn load_config() -> AppResult<Config> {
    let contents = fs::read_to_string(config_file())?;
    if contents.is_empty() {
        return Ok(Config::default());
    }
    Ok(serde_json::from_str(&contents)?)
}

fn save_config(repo_path: &str) -> AppResult<()> {
    let config = Config {
        repo: PathBuf::from(repo_path),
    };
    let contents = serde_json::to_string(&config)?;
    fs::write(config_file(), contents)?;
    Ok(())
}

fn clear_config() -> AppResult<()> {
    fs::remove_file(config_file())?;
    debug!(target: TARGET, "Cleared config");
    Ok(())
}

// ---------------------------------------------------------------------------
// Prompting
// ---------------------------------------------------------------------------

fn get_user_input(prompt: &str) -> AppResult<String> {
    loop {
        print!("\x1b[0m\x1b[1m\x1b[32m{}\n\x1b[0m> ", prompt);
        let _ = io::stdout().flush();
        let mut input = String::new();
        io::stdin().read_line(&mut input)?;
        let trimmed = input.trim().to_owned();
        if !trimmed.is_empty() {
            return Ok(trimmed);
        }
    }
}

// ---------------------------------------------------------------------------
// Locating and launching the editor / pager
// ---------------------------------------------------------------------------

#[derive(Debug)]
struct CannotFindBinaryPath;

impl fmt::Display for CannotFindBinaryPath {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "cannot find binary path")
    }
}
impl Error for CannotFindBinaryPath {}

#[cfg(unix)]
fn is_executable_file(path: &Path) -> bool {
    let Ok(meta) = fs::metadata(path) else {
        return false;
    };
    if !meta.is_file() {
        return false;
    }
    let Ok(cstr) = CString::new(path.as_os_str().as_bytes()) else {
        return false;
    };
    unsafe {
        libc::faccessat(libc::AT_FDCWD, cstr.as_ptr(), libc::X_OK, libc::AT_EACCESS) == 0
    }
}

#[cfg(not(unix))]
fn is_executable_file(path: &Path) -> bool {
    fs::metadata(path).map(|m| m.is_file()).unwrap_or(false)
}

fn which_program(name: &str) -> Result<PathBuf, CannotFindBinaryPath> {
    let Some(path_var) = env::var_os("PATH") else {
        return Err(CannotFindBinaryPath);
    };
    for dir in env::split_paths(&path_var) {
        let candidate = dir.join(name);
        if is_executable_file(&candidate) {
            return Ok(candidate);
        }
    }
    Err(CannotFindBinaryPath)
}

fn program_path(env_var: &str, fallback: &str) -> AppResult<PathBuf> {
    match env::var(env_var) {
        Ok(val) => Ok(PathBuf::from(val)),
        Err(_) => Ok(which_program(fallback)?),
    }
}

fn open_file_in_program(file_path: &str, env_var: &str, fallback: &str) -> AppResult<()> {
    let program = program_path(env_var, fallback)?;
    fs::metadata(file_path)?;
    ProcessCommand::new(program).arg(file_path).status()?;
    Ok(())
}

fn readme_path(config: &Config) -> String {
    format!("{}/README.md", config.repo.display())
}

fn view_ideas() -> AppResult<()> {
    let config = load_config()?;
    let path = readme_path(&config);
    open_file_in_program(&path, "PAGER", "less")?;
    Ok(())
}

// ---------------------------------------------------------------------------
// First-time setup
// ---------------------------------------------------------------------------

fn first_time_setup() -> AppResult<()> {
    let dir = config_dir();
    if !dir.exists() {
        fs::create_dir_all(&dir)?;
        debug!(target: TARGET, "Created config dir");
    }

    print!(
        "\x1b[0m\x1b[33m{}\n####                  First Time Setup                  ####\n{}\n\nThis tool requires you to have a repository with a README.md\nin the root folder. The markdown file is where your ideas\nwill be stored.\n\nOnce first time setup has completed, simply run Eureka again\nto begin writing down ideas.\n        \n\x1b[0m",
        "#".repeat(60),
        "#".repeat(60)
    );

    let repo_path = loop {
        let input = get_user_input("Absolute path to your idea repo")?;
        if Path::new(&input).is_absolute() {
            break input;
        }
        print!("\x1b[0m\x1b[31mPath must be absolute\n\x1b[0m");
    };

    save_config(&repo_path)?;
    debug!(target: TARGET, "Setup repo path successfully");
    println!("First time setup complete. Happy ideation!");
    Ok(())
}

// ---------------------------------------------------------------------------
// Git operations
// ---------------------------------------------------------------------------

fn checkout_main(repo: &Repository) -> AppResult<()> {
    let head = repo.head()?;
    let head_oid = head.target().unwrap();
    let head_commit = repo.find_commit(head_oid)?;

    // Ensure the local `main` branch exists, creating it at the current
    // HEAD when it does not.
    let _branch = repo
        .find_branch("main", BranchType::Local)
        .or_else(|_| repo.branch("main", &head_commit, false))?;

    let object = repo.revparse_single("refs/heads/main")?;
    let mut checkout_builder = CheckoutBuilder::default();
    repo.checkout_tree(&object, Some(&mut checkout_builder))?;
    repo.set_head("refs/heads/main")?;
    Ok(())
}

fn commit_idea(repo: &Repository, message: &str) -> AppResult<()> {
    println!("Adding and committing your new idea to main..");

    checkout_main(repo)?;

    let mut index = repo.index()?;
    index.add_path(Path::new("README.md"))?;
    index.write()?;
    let tree_oid = index.write_tree()?;
    let tree = repo.find_tree(tree_oid)?;
    let signature = repo.signature()?;
    let parent_commit = repo.head()?.peel_to_commit()?;
    repo.commit(
        Some("HEAD"),
        &signature,
        &signature,
        message,
        &tree,
        &[&parent_commit],
    )?;

    println!("Added and committed!");
    Ok(())
}

fn push_idea(repo: &Repository) -> AppResult<()> {
    println!("Pushing your new idea..");

    let mut remote = repo.find_remote("origin")?;
    let config = repo.config()?;

    let mut tried_ssh_key = false;
    let mut tried_credential_helper = false;
    let mut callbacks = RemoteCallbacks::new();
    callbacks.credentials(move |url, username_from_url, allowed_types| {
        if allowed_types.contains(CredentialType::USERNAME) {
            return match username_from_url {
                Some(username) => Cred::username(username),
                None => Err(git2::Error::from_str(
                    "No username specified in remote URL",
                )),
            };
        }
        if allowed_types.contains(CredentialType::SSH_KEY) && !tried_ssh_key {
            tried_ssh_key = true;
            let username = username_from_url.ok_or_else(|| {
                git2::Error::from_str("No username specified in remote URL")
            })?;
            return Cred::ssh_key_from_agent(username);
        }
        if allowed_types.contains(CredentialType::USERPASS_PLAINTEXT)
            && !tried_credential_helper
        {
            tried_credential_helper = true;
            return Cred::credential_helper(&config, url, username_from_url);
        }
        if allowed_types.contains(CredentialType::DEFAULT) {
            return Cred::default();
        }
        Err(git2::Error::from_str(
            "No authentication method succeeded",
        ))
    });

    let mut push_options = PushOptions::new();
    push_options.remote_callbacks(callbacks);
    remote.push(
        &["refs/heads/main:refs/heads/main"],
        Some(&mut push_options),
    )?;

    println!("Pushed!");
    Ok(())
}

fn capture_idea() -> AppResult<()> {
    let config = match load_config() {
        Ok(config) => config,
        Err(_) => {
            debug!(target: TARGET, "Config is missing");
            return first_time_setup();
        }
    };

    let idea_summary = get_user_input(">> Idea summary")?;
    let repo = Repository::open(&config.repo)?;
    let readme = readme_path(&config);

    // The editor, the commit and the push are all attempted in order.
    // A failure to launch the editor does not stop the idea from being
    // committed and pushed, but it is the first failure reported.
    let editor_result = open_file_in_program(&readme, "EDITOR", "vi");
    let commit_result = commit_idea(&repo, &idea_summary);
    let push_result = if commit_result.is_ok() {
        Some(push_idea(&repo))
    } else {
        None
    };

    let _ = VecDeque::<()>::new(); // (keep imports tidy across platforms)
    editor_result?;
    commit_result?;
    if let Some(push_result) = push_result {
        push_result?;
    }
    Ok(())
}

// ---------------------------------------------------------------------------

fn run(options: EurekaOptions) -> AppResult<()> {
    debug!(target: TARGET, "Running with options: {:?}", options);
    if options.clear_config {
        clear_config()
    } else if options.view {
        view_ideas()
    } else {
        capture_idea()
    }
}

fn main() {
    init_logger();
    let options = parse_options();
    if let Err(e) = run(options) {
        error!(target: TARGET, "{}", e);
    }
}
