        p=subprocess.run([link]+args,input=inp,env=env,cwd=scenario.get("cwd",root),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=5)
        out,err,ec=p.stdout,p.stderr,p.returncode
