def run_cmd(args, **kw):
    return subprocess.run(args, capture_output=True, text=True, **kw)

def setup_repo(repo, branch="main", readme=True, remote=False, no_commit=False):
    os.makedirs(repo, exist_ok=True)
    env=dict(os.environ); env.update({"GIT_AUTHOR_DATE":"1700000000 +0000","GIT_COMMITTER_DATE":"1700000000 +0000"})
    subprocess.run(["git","-C",repo,"init","-q","-b",branch],env=env)
    subprocess.run(["git","-C",repo,"config","user.email","a@a.com"]); subprocess.run(["git","-C",repo,"config","user.name","A"])
    if readme: open(repo+"/README.md","w").write("# Ideas\n")
    else: open(repo+"/other.txt","w").write("other\n")
    if not no_commit:
        subprocess.run(["git","-C",repo,"add","."]); subprocess.run(["git","-C",repo,"commit","-qm","init"],env=env)
    if remote:
        bare=repo+"-remote.git"; subprocess.run(["git","init","-q","--bare","-b","main",bare])
        subprocess.run(["git","-C",repo,"remote","add","origin",bare])
        if not no_commit: subprocess.run(["git","-C",repo,"push","-q","origin",branch],env=env)

def make_editor(root):
    ed=f"{root}/editor.sh"; open(ed,"w").write('#!/bin/sh\necho "editor:$@" >> "'+root+'/editor.log"\necho "Edited detail" >> "$1"\n'); os.chmod(ed,0o755)
    pg=f"{root}/pager.sh"; open(pg,"w").write('#!/bin/sh\necho "pager:$@" >> "'+root+'/pager.log"\ncat "$1"\n'); os.chmod(pg,0o755)

def git_summary(repo):
    if not os.path.exists(repo+"/.git"):
        return "no .git\n"
    out=[]
    def g(*a):
        p=run_cmd(["git","-C",repo]+list(a)); return (p.stdout+p.stderr).strip()
    out.append("HEADFILE="+(open(repo+"/.git/HEAD").read().strip() if os.path.exists(repo+"/.git/HEAD") else ""))
    out.append("STATUS:"+g("status","--short","--branch"))
    # branch refs -> commit subject + parents subjects
    refs=g("for-each-ref","--format=%(refname) %(objectname) %(*objectname)")
    out.append("REFSRAW:"+refs)
    # log all topological with parents hashes will normalize later by replacing hashes map globally from ref/log output
    out.append("LOG:"+g("log","--all","--format=%H|%P|%an|%ae|%s|%T"))
    out.append("LSFILES:"+g("ls-files","-s"))
    out.append("REFLOG_HEAD:"+g("reflog","--format=%gs"))
    out.append("REFLOG_MAIN:"+g("reflog","show","main","--format=%gs"))
    # worktree files (excluding .git)
    files=[]
    for root,dirs,fs in os.walk(repo):
        if '.git' in dirs: dirs.remove('.git')
        for f in sorted(fs):
            rel=os.path.relpath(os.path.join(root,f),repo)
            try: data=open(os.path.join(root,f),'rb').read()
            except Exception as e: data=str(e).encode()
            files.append(f"{rel}={data!r}")
    out.append("WT:" + ";".join(files))
    # tree listings per branch
    for line in refs.splitlines():
        ref=line.split()[0] if line.split() else ''
        if ref.startswith("refs/heads/"):
            out.append(f"TREE {ref}: "+g("ls-tree","-r",ref))
    return "\n".join(out)

def bare_summary(bare):
    if not os.path.exists(bare): return "no bare\n"
    p=run_cmd(["git","--git-dir",bare,"log","--all","--format=%H|%P|%s|%T"])
    r=run_cmd(["git","--git-dir",bare,"show-ref"])
    return "BARELOG:"+p.stdout.strip()+" BAREREFS:"+r.stdout.strip()

def home_summary(home, root):
    out=[]
    for r,ds,fs in os.walk(home):
        for d in sorted(ds): out.append("DIR "+os.path.relpath(os.path.join(r,d),home))
        for f in sorted(fs):
            path=os.path.join(r,f); out.append("FILE "+os.path.relpath(path,home)+"="+repr(open(path,'rb').read()))
