    // The libgit2 version available here understands several repository
    // extensions which the older libgit2 used by the reference binary
    // rejected (it only recognised "noop").  When a version 1 repository
    // declares any other extension, reproduce the older error instead of
    // happily opening the repository.
    let Ok(config) = repo.config() else {
        return Ok(());
    };
    let Ok(version) = config.get_i32("core.repositoryformatversion") else {
        return Ok(());
    };
    if version < 1 {
        return Ok(());
    }
    let Ok(mut entries) = config.entries(Some("^extensions\\\\.")) else {
        return Ok(());
    };
    while let Some(entry) = entries.next() {
        let Ok(entry) = entry else {
            return Ok(());
        };
        let name = String::from_utf8_lossy(entry.name_bytes()).into_owned();
        if name != "extensions.noop" {
            return Err(Box::new(git2::Error::new(
                ErrorCode::GenericError,
                ErrorClass::Repository,
                format!("unsupported extension name {}", name),
            )));
        }
    }
    Ok(())
}

'''
